/**
 * i18n dell'ADMIN (pannello di gestione), separato dall'i18n del sito
 * pubblico (src/i18n/ui.ts + fr/en.json).
 *
 * La lingua dell'admin è GLOBALE: la sceglie il super admin nella pagina
 * Réglages e viene salvata in app_config come "admin_lang". Le pagine admin
 * la leggono lato server con adminLang() (src/lib/admin/adminLang.ts) e usano
 * la funzione t = adminT(lang) per tradurre i testi.
 *
 * Il francese è la lingua predefinita e il fallback: qualsiasi chiave o
 * lingua mancante ricade sul francese, così l'admin non mostra mai "buchi".
 *
 * NB: la traduzione dell'admin è incrementale. Per ora sono tradotti la
 * barra di navigazione, l'header e la pagina Réglages del super admin; le
 * altre pagine restano in francese finché non aggiungiamo le loro chiavi.
 */

export const LINGUE_ADMIN = [
  { code: "fr", label: "Français" },
  { code: "en", label: "English" },
  { code: "it", label: "Italiano" },
  { code: "nl", label: "Nederlands" },
  { code: "es", label: "Español" },
] as const;

export type AdminLang = (typeof LINGUE_ADMIN)[number]["code"];

export const ADMIN_LANG_CODES: AdminLang[] = LINGUE_ADMIN.map((l) => l.code);
export const ADMIN_LANG_DEFAULT: AdminLang = "fr";

/** true se `v` è un codice lingua admin valido. */
export function isAdminLang(v: unknown): v is AdminLang {
  return typeof v === "string" && (ADMIN_LANG_CODES as string[]).includes(v);
}

