  "itg.g.placeLabel": { fr: "Place ID de l'établissement", en: "Place ID of the business", it: "Place ID dell'attività", nl: "Place ID van de zaak", es: "Place ID del establecimiento" },
  "itg.g.placeNote": { fr: "Trouve le Place ID sur Google Maps (fiche de l'établissement) ou via le « Place ID Finder » de Google. Permet d'afficher la note et les avis.", en: "Find the Place ID on Google Maps (business listing) or via Google's « Place ID Finder ». Lets you show the rating and reviews.", it: "Trova il Place ID su Google Maps (scheda dell'attività) o tramite il « Place ID Finder » di Google. Permette di mostrare valutazione e recensioni.", nl: "Vind de Place ID op Google Maps (bedrijfsvermelding) of via Google's « Place ID Finder ». Toont beoordeling en recensies.", es: "Encuentra el Place ID en Google Maps (ficha del negocio) o con el « Place ID Finder » de Google. Permite mostrar la valoración y las reseñas." },
  "itg.g.lvl2": { fr: "Niveau 2 · répondre aux avis, synchroniser les horaires", en: "Level 2 · reply to reviews, sync opening hours", it: "Livello 2 · rispondere alle recensioni, sincronizzare gli orari", nl: "Niveau 2 · reageren op recensies, openingsuren synchroniseren", es: "Nivel 2 · responder reseñas, sincronizar horarios" },
