  "itg.g.connectedNote": { fr: "Fiche Google connectée : réponses aux avis et horaires synchronisables.", en: "Google listing connected: review replies and hours can be synced.", it: "Scheda Google connessa: risposte alle recensioni e orari sincronizzabili.", nl: "Google-vermelding verbonden: recensieantwoorden en uren kunnen worden gesynchroniseerd.", es: "Ficha de Google conectada: respuestas a reseñas y horarios sincronizables." },
  "itg.g.authNote": { fr: "Le client autorise MOODD à gérer sa fiche Google.", en: "The client lets MOODD manage its Google listing.", it: "Il cliente autorizza MOODD a gestire la sua scheda Google.", nl: "De klant staat MOODD toe zijn Google-vermelding te beheren.", es: "El cliente autoriza a MOODD a gestionar su ficha de Google." },
  "itg.g.needPlace": { fr: "Colle d'abord un Place ID.", en: "Paste a Place ID first.", it: "Incolla prima un Place ID.", nl: "Plak eerst een Place ID.", es: "Pega primero un Place ID." },
  "itg.g.isKey": { fr: "Ça, c'est une clé API Google (elle va dans le .env). Ici on attend le Place ID de l'établissement (ChIJ…).", en: "That's a Google API key (it goes in the .env). Here we expect the business Place ID (ChIJ…).", it: "Questa è una chiave API Google (va nel .env). Qui serve il Place ID dell'attività (ChIJ…).", nl: "Dat is een Google API-sleutel (die hoort in de .env). Hier verwachten we de Place ID van de zaak (ChIJ…).", es: "Eso es una clave API de Google (va en el .env). Aquí se espera el Place ID del establecimiento (ChIJ…)." },
  "itg.g.isKeyShort": { fr: "C'est une clé API, pas un Place ID.", en: "That's an API key, not a Place ID.", it: "È una chiave API, non un Place ID.", nl: "Dat is een API-sleutel, geen Place ID.", es: "Es una clave API, no un Place ID." },
