  "itg.sc.who": { fr: "Visibilité sur Google : clics, impressions et mots-clés qui mènent au site.", en: "Visibility on Google: clicks, impressions and keywords that lead to the site.", it: "Visibilità su Google: clic, impressioni e parole chiave che portano al sito.", nl: "Zichtbaarheid op Google: klikken, vertoningen en zoekwoorden die naar de site leiden.", es: "Visibilidad en Google: clics, impresiones y palabras clave que llevan al sitio." },
