  "itg.sc.step1": { fr: "1. Ajoute ce compte comme utilisateur dans la Search Console du client (Réglages → Utilisateurs et autorisations → Ajouter, autorisation « Complète » ou « Restreinte ») :", en: "1. Add this account as a user in the client's Search Console (Settings → Users and permissions → Add, « Full » or « Restricted » permission):", it: "1. Aggiungi questo account come utente nella Search Console del cliente (Impostazioni → Utenti e autorizzazioni → Aggiungi, autorizzazione « Completa » o « Con limitazioni ») :", nl: "1. Voeg dit account toe als gebruiker in de Search Console van de klant (Instellingen → Gebruikers en machtigingen → Toevoegen, machtiging « Volledig » of « Beperkt »):", es: "1. Añade esta cuenta como usuario en la Search Console del cliente (Configuración → Usuarios y permisos → Añadir, permiso « Completo » o « Restringido »):" },
  "itg.sc.step2": { fr: "2. Propriété Search Console du client", en: "2. Client's Search Console property", it: "2. Proprietà Search Console del cliente", nl: "2. Search Console-property van de klant", es: "2. Propiedad de Search Console del cliente" },
  "itg.sc.note": { fr: "Propriété domaine : sc-domain:exemple.be. Propriété préfixe d'URL : l'adresse complète, ex. https://www.exemple.be/.", en: "Domain property: sc-domain:example.be. URL-prefix property: the full address, e.g. https://www.example.be/.", it: "Proprietà dominio: sc-domain:esempio.be. Proprietà prefisso URL: l'indirizzo completo, es. https://www.esempio.be/.", nl: "Domein-property: sc-domain:voorbeeld.be. URL-voorvoegsel-property: het volledige adres, bijv. https://www.voorbeeld.be/.", es: "Propiedad de dominio: sc-domain:ejemplo.be. Propiedad de prefijo de URL: la dirección completa, ej. https://www.ejemplo.be/." },
  "itg.sc.needSite": { fr: "Indique d'abord la propriété (sc-domain:… ou https://…).", en: "Enter the property first (sc-domain:… or https://…).", it: "Indica prima la proprietà (sc-domain:… o https://…).", nl: "Geef eerst de property op (sc-domain:… of https://…).", es: "Indica primero la propiedad (sc-domain:… o https://…)." },
  "itg.sc.notFound": { fr: "Propriété non trouvée — vérifie le format et que le robot a bien été ajouté.", en: "Property not found — check the format and that the robot was added.", it: "Proprietà non trovata — controlla il formato e che il robot sia stato aggiunto.", nl: "Property niet gevonden — controleer het formaat en of de robot is toegevoegd.", es: "Propiedad no encontrada — comprueba el formato y que se añadió el robot." },
  "itg.sc.okStats": { fr: "clics · {imp} impressions (28 derniers jours).", en: "clicks · {imp} impressions (last 28 days).", it: "clic · {imp} impressioni (ultimi 28 giorni).", nl: "klikken · {imp} vertoningen (laatste 28 dagen).", es: "clics · {imp} impresiones (últimos 28 días)." },
