/**
 * Restituisce la funzione di traduzione per la lingua data.
 * t(key) → testo nella lingua scelta, con fallback su FR e infine sulla
 * chiave stessa (così un eventuale buco è subito visibile in sviluppo).
 */
export function adminT(lang: AdminLang) {
  return function t(key: string): string {
    const riga = DIZIONARIO[key];
    if (!riga) return key;
    return riga[lang] ?? riga[ADMIN_LANG_DEFAULT] ?? key;
  };
}
